function weekKey(d=new Date()){const n=new Date(d);const day=n.getDay()||7;n.setDate(n.getDate()-day+1);return n.toLocaleDateString('sv-SE')}
function defaultWeek():WeekSlot[]{return [0,1,2,3,4,5,6].map(day=>({day,type:'Frei',done:false}))}
function estimateActivityKcal(type:ActivityType,duration:number,weight:number){return Math.round(activityMET[type]*3.5*weight/200*duration)}
const workoutIntensityMET={locker:3.5,moderat:5,intensiv:7} as const;
function estimateWorkoutKcal(intensity:'locker'|'moderat'|'intensiv',duration:number,weight:number){return Math.round(workoutIntensityMET[intensity]*3.5*weight/200*duration)}

